"""Maximum input byte size: 6144 rows x 32 fields with long ID values."""
import json, random, sys, subprocess, time
from collections import Counter

def build(seed=0):
    rnd = random.Random(seed)
    longid = 'A' * 32
    vals = [longid, 'B' * 32, 'C' * 31]
    schema = []
    for i in range(32):
        t = ['TIME', 'SIZE', 'COUNT', 'ID', 'FLAG'][i % 5]
        name = 'field_with_a_long_name_%02d' % i if False else 'f%02d' % i
        if t == 'ID':
            schema.append({'name': name, 'type': 'ID', 'values': vals})
        elif t == 'FLAG':
            schema.append({'name': name, 'type': 'FLAG'})
        else:
            schema.append({'name': name, 'type': t, 'min': -2000000, 'max': 2000000})
    K = 8
    numeric = [f for f in schema if f['type'] in ('TIME', 'SIZE', 'COUNT')]
    atoms = []
    for idx in range(20):
        ftype = numeric[idx % len(numeric)]['type']
        same = [f for f in numeric if f['type'] == ftype]
        fname = same[idx % len(same)]['name']
        atoms.append({'quantifier': 'any', 'from': 0, 'to': K - 1,
                      'predicate': {'cmp': 'ge',
                                    'left': {'field': fname, 'at': '$'},
                                    'right': {'const': 0, 'type': ftype}}})
    def rand_row():
        out = []
        for f in schema:
            if f['type'] == 'ID': out.append(rnd.choice(vals))
            elif f['type'] == 'FLAG': out.append(rnd.random() < 0.5)
            else: out.append(rnd.randint(-2000000, 2000000))
        return out
    def trace(tid, src, n):
        return {'id': tid, 'source': src,
                'rows': [{'t': i * 7 - 100000, 'values': rand_row()} for i in range(n)]}
    train = [trace('T%02d' % i, 's%d' % (i % 16), 263) for i in range(16)]
    probes = [trace('P%02d' % i, 's0', 15) for i in range(16)]
    queries = [trace('Q%02d' % i, 's0', 55) for i in range(19)] + [trace('Q19', 's0', 47)]
    return {'version': 1, 'schema': schema, 'window': K, 'atoms': atoms,
            'policy': {'max_width': 4, 'min_support': 1, 'min_witness': 1},
            'train': train, 'probes': probes, 'queries': queries}

req = build()
data = json.dumps(req).encode()
print('rows=%d bytes=%d' % (sum(len(t['rows']) for t in req['train']+req['probes']+req['queries']), len(data)), file=sys.stderr)
t0 = time.time()
p = subprocess.run([sys.executable, '/app/submission/main.py'], input=data, capture_output=True)
print('rc=%d wall=%.2fs %s' % (p.returncode, time.time()-t0, p.stderr.decode()[-300:]))
r = json.loads(p.stdout.decode())
if 'error' in r: print('ERROR', r)
else:
    print('classes=%d members=%d queries=%d' % (len(r['classes']), sum(c['members'] for c in r['classes']), len(r['queries'])))
    print('statuses', Counter(q['status'] for q in r['queries']))
    print('out bytes', len(p.stdout))
